package com.kelompok4.oralhealthplus.data.local

import android.content.Context
import android.content.SharedPreferences

// Generated by Local AI (qwen2.5-coder:7b)
class SessionManager(context: Context) {
    private val sharedPreferences: SharedPreferences = context.getSharedPreferences("oralhealth_session", Context.MODE_PRIVATE)

    fun saveSession(username: String, displayName: String, authProvider: String = "LOCAL") {
        with(sharedPreferences.edit()) {
            putString("username", username)
            putString("displayName", displayName)
            putString("authProvider", authProvider)
            apply()
        }
    }

    fun isLoggedIn(): Boolean {
        return sharedPreferences.getString("username", null) != null
    }

    fun getLoggedInUsername(): String? {
        return sharedPreferences.getString("username", null)
    }

    fun getDisplayName(): String {
        return sharedPreferences.getString("displayName", "") ?: ""
    }

    fun getAuthProvider(): String {
        return sharedPreferences.getString("authProvider", "LOCAL") ?: "LOCAL"
    }

    fun clearSession() {
        with(sharedPreferences.edit()) {
            remove("username")
            remove("displayName")
            remove("authProvider")
            apply()
        }
    }
}
